import{_ as e,a0 as a,w as o,s as p,I as n,x as i,a1 as s,A as u,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"如何在 Linux 下安裝安卓文件傳輸助手 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 下安裝安卓文件傳輸助手 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 下安裝安卓文件傳輸助手 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 下安裝安卓文件傳輸助手 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171124 How to Install Android File Transfer for Linux","title":"如何在 Linux 下安裝安卓文件傳輸助手","tag":"201712","desc":""},"relativePath":"201712/20171124 How to Install Android File Transfer for Linux.md","filePath":"[post].md"}'),d={name:"201712/20171124 How to Install Android File Transfer for Linux.md"};function f(g,t,x,m,b,w){const l=a("Link");return o(),p("div",null,[t[19]||(t[19]=n("h1",{id:"如何在-linux-下安裝安卓文件傳輸助手",tabindex:"-1"},[i("如何在 Linux 下安裝安卓文件傳輸助手 "),n("a",{class:"header-anchor",href:"#如何在-linux-下安裝安卓文件傳輸助手","aria-label":"Permalink to “如何在 Linux 下安裝安卓文件傳輸助手”"},"​")],-1)),t[20]||(t[20]=n("p",null,"如果你嘗試在 Ubuntu 下連接你的安卓手機，你也許可以試試 Linux 下的安卓文件傳輸助手。",-1)),t[21]||(t[21]=n("p",null,"本質上來説，這個應用是谷歌 macOS 版本的一個克隆。它是用 Qt 編寫的，用户界面非常簡潔，使得你能輕鬆在 Ubuntu 和安卓手機之間傳輸文件和文件夾。",-1)),t[22]||(t[22]=n("p",null,"現在，有可能一部分人想知道有什麼是這個應用可以做，而 Nautilus（Ubuntu 默認的文件資源管理器）不能做的，答案是沒有。",-1)),n("p",null,[t[2]||(t[2]=i("當我將我的 Nexus 5X（記得選擇 ",-1)),s(l,{href:"https://en.wikipedia.org/wiki/Media_Transfer_Protocol"},{default:u(()=>[...t[0]||(t[0]=[i("媒體傳輸協議 MTP",-1)])]),_:1}),t[3]||(t[3]=i(" 選項）連接在 Ubuntu 上時，在 ",-1)),s(l,{href:"https://en.wikipedia.org/wiki/GVfs"},{default:u(()=>[...t[1]||(t[1]=[i("GVfs",-1)])]),_:1}),t[4]||(t[4]=i("（LCTT 譯註： GNOME 桌面下的虛擬文件系統）的幫助下，我可以打開、瀏覽和管理我的手機，就像它是一個普通的 U 盤一樣。",-1))]),n("p",null,[s(l,{href:"http://www.omgubuntu.co.uk/wp-content/uploads/2017/11/browsing-android-mtp-nautilus.jpg"},{default:u(()=>[...t[5]||(t[5]=[n("img",{src:"http://www.omgubuntu.co.uk/wp-content/uploads/2017/11/browsing-android-mtp-nautilus.jpg",alt:"Nautilus MTP integration with a Nexus 5X"},null,-1)])]),_:1})]),t[23]||(t[23]=r('<p>但是<em>一些</em>用户在使用默認的文件管理器時，在 MTP 的某些功能上會出現問題：比如文件夾沒有正確加載，創建新文件夾後此文件夾不存在，或者無法在媒體播放器中使用自己的手機。</p><p>這就是要為 Linux 系統用户設計一個安卓文件傳輸助手應用的原因，將這個應用當做將 MTP 設備安裝在 Linux 下的另一種選擇。如果你使用 Linux 下的默認應用時一切正常，你也許並不需要嘗試使用它 (除非你真的很想嘗試新鮮事物)。</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2017/11/android-file-transfer-for-linux-750x662.jpg" alt="Android File Transfer Linux App"></p><p>該 app 特點：</p><ul><li>簡潔直觀的用户界面</li><li>支持文件拖放功能（從 Linux 系統到手機）</li><li>支持批量下載 (從手機到 Linux系統)</li><li>顯示傳輸進程對話框</li><li>FUSE 模組支持</li><li>沒有文件大小限制</li><li>可選命令列工具</li></ul><h3 id="ubuntu-下安裝安卓手機文件助手的步驟" tabindex="-1">Ubuntu 下安裝安卓手機文件助手的步驟 <a class="header-anchor" href="#ubuntu-下安裝安卓手機文件助手的步驟" aria-label="Permalink to “Ubuntu 下安裝安卓手機文件助手的步驟”">​</a></h3><p>以上就是對這個應用的介紹，下面是如何安裝它的具體步驟。</p><p>這有一個 [PPA]（個人軟件包集）源為 Ubuntu 14.04 LTS、16.04 LTS 和 Ubuntu 17.10 提供可用應用。</p><p>為了將這一 PPA 加入你的軟件資源列表中，執行這條命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:samoilov-lex/aftl-stable</span></span></code></pre></div><p>接着，為了在 Ubuntu 下安裝 Linux版本的安卓文件傳輸助手，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get update &amp;&amp; sudo apt install android-file-transfer</span></span></code></pre></div><p>這樣就行了。</p><p>你會在你的應用列表中發現這一應用的啓動圖標。</p><p>在你啓動這一應用之前，要確保沒有其他應用（比如 Nautilus）已經掛載了你的手機。如果其它應用正在使用你的手機，就會顯示“無法找到 MTP 設備”。要解決這一問題，將你的手機從 Nautilus（或者任何正在使用你的手機的應用）上移除，然後再重新啓動安卓文件傳輸助手。</p><hr>',16)),n("p",null,[t[7]||(t[7]=i("via: ",-1)),s(l,{href:"http://www.omgubuntu.co.uk/2017/11/android-file-transfer-app-linux"},{default:u(()=>[...t[6]||(t[6]=[i("http://www.omgubuntu.co.uk/2017/11/android-file-transfer-app-linux",-1)])]),_:1})]),n("p",null,[t[11]||(t[11]=i("作者：",-1)),s(l,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:u(()=>[...t[8]||(t[8]=[i("JOEY SNEDDON",-1)])]),_:1}),t[12]||(t[12]=i(" 譯者：",-1)),s(l,{href:"https://github.com/wenwensnow"},{default:u(()=>[...t[9]||(t[9]=[i("wenwensnow",-1)])]),_:1}),t[13]||(t[13]=i(" 校對：",-1)),s(l,{href:"https://github.com/wxy"},{default:u(()=>[...t[10]||(t[10]=[i("wxy",-1)])]),_:1})]),n("p",null,[t[16]||(t[16]=i("本文由 ",-1)),s(l,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[14]||(t[14]=[i("LCTT",-1)])]),_:1}),t[17]||(t[17]=i(" 原創編譯，",-1)),s(l,{href:"https://linux.cn/"},{default:u(()=>[...t[15]||(t[15]=[i("Linux中國",-1)])]),_:1}),t[18]||(t[18]=i(" 榮譽推出",-1))])])}const C=e(d,[["render",f]]);export{L as __pageData,C as default};
